function DriveVersionControl({versions,selected,loaded,loading,error,busy,historical,pinningEnabled,language,onOpen,onSelect,onRestore}:{versions:DriveVersion[];selected?:DriveVersion;loaded:boolean;loading:boolean;error:string;busy:boolean;historical:boolean;pinningEnabled:boolean;language:LanguageCode;onOpen:()=>void;onSelect:(version:DriveVersion)=>void;onRestore:()=>void}){
 const activeVersion=selected||versions.find(version=>version.current)||versions[versions.length-1]
 const t=(value:string)=>uiText(value,language),label=activeVersion?uiMessage('v{number} of {count}',language,{number:activeVersion.number,count:versions.length}):t(loading?'Loading versions…':error?'Versions unavailable':'Versions')
 const choose=(event:React.MouseEvent<HTMLButtonElement>,version:DriveVersion)=>{event.currentTarget.closest('details')?.removeAttribute('open');onSelect(version)}
 const open=(event:React.SyntheticEvent<HTMLDetailsElement>)=>{if(event.currentTarget.open&&!loading)onOpen()}
 return <span className="drive-version-controls"><details className="drive-version-picker" onToggle={open}><summary aria-label={t('Show version history')} title={t('Version history loads only when opened')}><span>{label}</span><span className="version-chevron" aria-hidden="true">⌄</span></summary><div className="drive-version-menu" role="menu" aria-label={t('Available Google Drive versions')}>{loading?<p>{t('Loading version history from Google Drive…')}</p>:error?<><p className="version-error">{t(error)}</p><button type="button" role="menuitem" onClick={onOpen}><strong>{t('Retry')}</strong><span>{t('Load version history')}</span></button></>:versions.length?[...versions].reverse().map(version=>{const unavailable=!pinningEnabled&&!version.current&&!version.keepForever;return <button type="button" role="menuitem" key={version.id} className={version.id===activeVersion?.id?'selected':''} disabled={busy||version.id===activeVersion?.id||unavailable} title={unavailable?t('Unarchive the trip to retain and open this version'):undefined} onClick={event=>choose(event,version)}><strong>v{version.number}</strong><span>{updatedFmt(version.modifiedTime,language)}</span>{version.current?<small>{t('Current')}</small>:unavailable?<small>{t('Unarchive to open')}</small>:version.keepForever?<small>{t('Retained')}</small>:null}</button>}):<p>{t(loaded?'Google Drive did not return any versions for this trip.':'Version history is fetched only when this menu is opened.')}</p>}{versions.length>0&&<p>{t(pinningEnabled?'v1 is the oldest version currently available. Opening an older version retains it in Drive.':'This trip is archived. Existing retained versions remain available, but no new versions are pinned.')}</p>}</div></details>{historical&&<button type="button" className="restore-version-icon" title="Restore as local copy" aria-label="Restore as local copy" disabled={busy} onClick={onRestore}><RestoreVersionIcon/></button>}</span>
}

function RestoreVersionIcon(){
 return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8v5h5"/><path d="M5.5 12A7 7 0 1 1 8 17.5"/><path d="M12 8v5l3 2"/></svg>
}

function TripListRow({name,details,tripDates,updatedAt,active,favourite,synced,shared,accessMode,hasCalendar,drive=false,language,onOpen,onToggleFavourite}:{name:string;details:string;tripDates:string;updatedAt?:string;active:boolean;favourite:boolean;synced:boolean;shared:boolean;accessMode?:SavedShareAccessMode;hasCalendar:boolean;drive?:boolean;language:LanguageCode;onOpen:()=>void;onToggleFavourite:()=>void}){
 const t=(value:string)=>uiText(value,language),tripDateLabel=tripDates===t('No trip dates yet')?t('Trip dates not set'):uiMessage('Trip {dates}',language,{dates:tripDates}),favouriteLabel=`${t(favourite?'Remove from favourites':'Add to favourites')}: ${name}`
 return <article className={`${active?'active-trip ':''}${drive?'drive-trip-row':''}`}><button type="button" className="trip-open-button" onClick={onOpen}><strong className="trip-list-title"><span>{name}</span>{(synced||shared||hasCalendar)&&<span className="trip-status-icons">{synced&&<SyncedTripIcon language={language}/>} {shared&&(accessMode?<SharedAccessIcon mode={accessMode}/>:<SharedTripIcon language={language}/>)} {hasCalendar&&<TripCalendarIcon language={language}/>}</span>}</strong><span>{t(details)}</span><small className="trip-date-summary"><span>{tripDateLabel}</span><span>{uiMessage('Last updated {date}',language,{date:updatedFmt(updatedAt,language)})}</span></small></button><button type="button" className={`favourite-toggle${favourite?' selected':''}`} aria-label={favouriteLabel} aria-pressed={favourite} title={favouriteLabel} onClick={onToggleFavourite}>{favourite?'★':'☆'}</button></article>
}

