function LanguagePicker({language,onSelect}:{language:LanguageCode;onSelect:(language:LanguageCode)=>void}){
 const pickerRef=useRef<HTMLDetailsElement>(null),selected=languageMetadata[language]
 useEffect(()=>{const close=(event:PointerEvent)=>{if(pickerRef.current&&!pickerRef.current.contains(event.target as Node))pickerRef.current.removeAttribute('open')};document.addEventListener('pointerdown',close);return()=>document.removeEventListener('pointerdown',close)},[])
 const select=(code:LanguageCode)=>{onSelect(code);pickerRef.current?.removeAttribute('open');pickerRef.current?.querySelector('summary')?.focus()}
 return <details className="language-picker" ref={pickerRef} onKeyDown={event=>{if(event.key==='Escape'){event.preventDefault();pickerRef.current?.removeAttribute('open');pickerRef.current?.querySelector('summary')?.focus()}}}><summary aria-label="Language" aria-haspopup="menu" title={selected.name}><span className="language-picker-flag" aria-hidden="true">{selected.flag}</span><span className="language-picker-chevron" aria-hidden="true">⌄</span></summary><div className="language-picker-menu" role="menu" aria-label="Language">{languageCodes.map(code=>{const option=languageMetadata[code],active=code===language;return <button type="button" role="menuitemradio" aria-checked={active} className={active?'selected':''} lang={option.htmlLang} key={code} onClick={()=>select(code)}><span className="language-option-flag" aria-hidden="true">{option.flag}</span><span>{option.name}</span>{active&&<span className="language-option-check" aria-hidden="true">✓</span>}</button>})}</div></details>
}

function RouteOverview({segments,selected,collapsed,mapProvider,language,onSelect,onToggleCollapsed}:{segments:GroundRouteSegment[];selected:string;collapsed:boolean;mapProvider:MapProvider;language:LanguageCode;onSelect:(value:string)=>void;onToggleCollapsed:()=>void}){
 const stops=segments.flatMap(segment=>segment.stops),selectedSegment=segments.find(segment=>segment.stops.some((_,index)=>routeStepFlightFilterId(segment,index)===selected))
 return <section className={`route-overview ${collapsed?'route-collapsed':''}`} aria-label={uiText('Trip route and destination filters',language)} onClick={()=>onSelect('all')}><div className="route-heading"><div><span className="eyebrow">{uiText('TRIP ROUTE',language)}</span><strong>{selected==='all'?(segments.length===1?segments[0].label:`${segments.length} trip segments`):stops.find(stop=>stop.id===selected)?.label||selectedSegment?.label}</strong></div><div className="route-actions"><button type="button" className="route-collapse" aria-label={uiText(`${collapsed?'Expand':'Collapse'} trip route`,language)} aria-expanded={!collapsed} onClick={event=>{event.stopPropagation();onToggleCollapsed()}}><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7.5 5 5 5-5"/></svg></button></div></div>{!collapsed&&segments.map(segment=>{const mapLinks=mapDirectionsUrls(segment.mapStops||segment.stops,mapProvider);return <div className="route-segment" key={segment.id}><div className="route-segment-heading"><strong>{segment.label}</strong><div className="route-actions">{mapLinks.map((link,index)=><a key={link} href={link} target="_blank" rel="noreferrer" onClick={event=>event.stopPropagation()}>{uiMessage(mapLinks.length>1?'Open {destination} part {part} in Google Maps ↗':'Open {destination} in Google Maps ↗',language,{destination:segment.label,part:index+1})}</a>)}</div></div><div className="route-track">{segment.stops.map((stop,index)=>{const flightRoutes=[index===0?segment.arrivalFlightRoute:undefined,index===segment.stops.length-1?segment.departureFlightRoute:undefined].filter((route):route is string[]=>!!route?.length),flightFilterId=routeStepFlightFilterId(segment,index),filterId=flightFilterId||stop.id,isSelected=selected===filterId;return <Fragment key={`${stop.address}-${index}`}>{index>0&&<span className="route-arrow" aria-hidden="true">→</span>}<button type="button" className={isSelected?'selected':''} aria-pressed={isSelected} title={stop.address} onClick={event=>{event.stopPropagation();onSelect(isSelected?'all':filterId)}}><span className="route-pin" aria-hidden="true">{index+1}</span><strong className={flightRoutes.length?'route-flight-routes':''}>{flightRoutes.length?flightRoutes.map((route,routeIndex)=><span className="flight-route-code" key={`${route.join('-')}-${routeIndex}`}><span aria-hidden="true">✈</span>{route.join('/')}</span>):stop.label}</strong></button></Fragment>})}</div></div>})}</section>
}

function EditableTripTitle({value,language,onSave}:{value:string;language:LanguageCode;onSave:(value:string)=>void}){
 const [editing,setEditing]=useState(false),[draft,setDraft]=useState(value)
 useEffect(()=>{if(!editing)setDraft(value)},[value,editing])
 const commit=()=>{const next=draft.trim();setEditing(false);if(next&&next!==value)onSave(next);else setDraft(value)}
 if(editing)return <input className="editable-title-input" aria-label={uiText('Trip title',language)} autoFocus value={draft} onChange={e=>setDraft(e.target.value)} onFocus={e=>e.currentTarget.select()} onBlur={commit} onKeyDown={e=>{if(e.key==='Escape'){e.preventDefault();setDraft(value);setEditing(false)}else if(e.key==='Enter')e.currentTarget.blur()}}/>
 return <button type="button" className="editable-title" title={uiText('Edit trip title',language)} onClick={()=>setEditing(true)}>{value}</button>
}

function ItemModal({item,items,language,canAccessSourceEmails,canAddJournal,driveConnected,onClose,onSave,onDelete}:{item:TripItem;items:TripItem[];language:LanguageCode;canAccessSourceEmails:boolean;canAddJournal:boolean;driveConnected:boolean;onClose:()=>void;onSave:(items:TripItem[],photoFiles?:File[],removedPhotos?:JournalPhoto[],audioFiles?:File[],removedAudio?:JournalAudio[])=>void|Promise<void>;onDelete:()=>void}){
 const [v,setV]=useState(item),[tab,setTab]=useState<'details'|'json'>('details'),[json,setJson]=useState(()=>formatTripItemJson(item)),[jsonError,setJsonError]=useState(''),[copyStatus,setCopyStatus]=useState(''),[detailsHeight,setDetailsHeight]=useState(0),[photoFiles,setPhotoFiles]=useState<File[]>([]),[audioFiles,setAudioFiles]=useState<File[]>([]),[removedPhotos,setRemovedPhotos]=useState<JournalPhoto[]>([]),[removedAudio,setRemovedAudio]=useState<JournalAudio[]>([]),[busy,setBusy]=useState(false),modalRef=useRef<HTMLFormElement>(null)
 const t=(value:string)=>uiText(value,language),isNew=!items.some(value=>value.id===item.id),isJournal=v.type==='journal',hasEndDetails=['flight','transport'].includes(v.type),relatedItems=items.filter(value=>value.type!=='journal'&&value.id!==v.id)
 const field=(key:keyof TripItem)=>(event:ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>setV(current=>({...current,[key]:event.target.value}))
 const selectType=(event:ChangeEvent<HTMLSelectElement>)=>{const type=event.target.value as ItemType;setV(current=>({...current,type}))}
 const selectRelated=(event:ChangeEvent<HTMLSelectElement>)=>{const related=relatedItems.find(value=>value.id===event.target.value);setV(current=>copyRelatedDetailsToJournal(current,related))}
 const removePhoto=(photo:JournalPhoto)=>{setV(current=>({...current,photos:(current.photos||[]).filter(value=>value.id!==photo.id)}));setRemovedPhotos(current=>[...current,photo])}
 const removeAudio=(clip:JournalAudio)=>{setV(current=>({...current,audio:(current.audio||[]).filter(value=>value.id!==clip.id)}));setRemovedAudio(current=>[...current,clip])}
 const selectTab=(next:'details'|'json')=>{if(next==='json'){if(modalRef.current)setDetailsHeight(modalRef.current.getBoundingClientRect().height);setJson(formatTripItemJson(v))}setTab(next);setJsonError('');setCopyStatus('')}
 const submit=async(event:React.FormEvent)=>{event.preventDefault();if(tab==='json'){const result=parseTripItemsJson(json,isNew?uid:()=>item.id);if(!result.ok){setJsonError(result.error);return}if(!isNew&&result.items.length!==1){setJsonError('Overwrite an existing entry with exactly one item object.');return}const safeItems=result.items.map(candidate=>retainExistingDriveJournalMedia(candidate,isNew?undefined:item));setJsonError('');setBusy(true);try{await onSave(safeItems)}finally{setBusy(false)}return}setBusy(true);try{await onSave([itemFromEditor({...v,link:safeHttpsLink(v.link),emailLink:safeHttpsLink(v.emailLink)})],isJournal?photoFiles:[],removedPhotos,isJournal?audioFiles:[],removedAudio)}finally{setBusy(false)}}
 const copyItem=async()=>setCopyStatus(t(await copyText(json||formatTripItemJson(v))?'Item JSON copied.':'Select the JSON and use your browser’s Copy command.'))
 return <div className="modal-backdrop" onMouseDown={onClose}><form ref={modalRef} className={`modal item-modal ${isJournal?'item-modal-journal ':''}${tab==='json'?'item-modal-json':''}`} style={detailsHeight?{minHeight:detailsHeight}:undefined} onMouseDown={event=>event.stopPropagation()} onSubmit={submit}>
  <div className="modal-title"><h2>{t(isNew?'Add item':'Edit item')}</h2><button type="button" className="close" aria-label={t('Close')} title={t('Close')} onClick={onClose}>×</button></div>
  <div className="item-editor-tabs" role="tablist" aria-label={t('Item editor')}><button type="button" role="tab" aria-selected={tab==='details'} className={tab==='details'?'selected':''} onClick={()=>selectTab('details')}>{t('Details')}</button><button type="button" role="tab" aria-selected={tab==='json'} className={tab==='json'?'selected':''} onClick={()=>selectTab('json')}>JSON</button></div>
  {tab==='details'?<>
   <label>Type<select value={v.type} onChange={selectType}>{types.filter(type=>type!=='journal'||canAddJournal||item.type==='journal').map(type=><option value={type} key={type}>{typeLabels[type]}</option>)}</select></label>
   <label>Title<input required value={v.title} onChange={field('title')}/></label>
   {v.type==='flight'&&<div className="two"><label>Flight number<input value={v.flightNumber||''} onChange={field('flightNumber')}/></label><label>Duration (minutes)<input type="number" min="0" value={v.durationMinutes||''} onChange={event=>setV(current=>({...current,durationMinutes:event.target.value?Number(event.target.value):undefined}))}/></label></div>}
   {isJournal&&<label>{t('Related itinerary item')}<select value={v.relatedItemId||''} onChange={selectRelated}><option value="">{t('None — enter details manually')}</option>{relatedItems.map(related=><option value={related.id} key={related.id}>{related.title} · {related.start.replace('T',' ')}</option>)}</select></label>}
   <div className="two"><label>Starts<input type="datetime-local" required value={v.start} onChange={event=>setV(current=>({...current,start:event.target.value,allDay:false}))}/></label><label>Ends<input type="datetime-local" value={v.end||''} onChange={field('end')}/></label></div>
   {(v.type==='event'||isJournal)&&<label className="checkbox-label"><input type="checkbox" checked={!!v.allDay} onChange={event=>setV(current=>({...current,allDay:event.target.checked}))}/> Time not specified</label>}
   <datalist id="waypoint-time-zones">{zones.map(zone=><option key={zone} value={zone}/>)}</datalist>
   {isJournal?<Fragment key="journal-fields">
    <label>Time zone<input list="waypoint-time-zones" required value={v.timeZone} onChange={field('timeZone')}/></label>
    <label>Location<input value={v.location||''} onChange={field('location')}/></label>
    <label>{t('Notes')}<textarea className="journal-editor" value={v.notes||''} onChange={field('notes')} placeholder={t('What happened?')}/></label>
    {((v.photos||[]).length>0||photoFiles.length>0)&&<div className="journal-photo-grid journal-photo-editor">{(v.photos||[]).map(photo=><figure key={photo.id}><DriveJournalPhoto photo={photo} connected={driveConnected} language={language}/><button type="button" className="danger" onClick={()=>removePhoto(photo)}>{t('Remove')}</button></figure>)}{photoFiles.map((file,index)=><figure key={`${file.name}-${file.lastModified}-${index}`}><LocalJournalPhoto file={file} language={language}/><button type="button" className="danger" onClick={()=>setPhotoFiles(current=>current.filter((_,candidate)=>candidate!==index))}>{t('Remove')}</button></figure>)}</div>}
    {((v.audio||[]).length>0||audioFiles.length>0)&&<div className="journal-audio-list journal-audio-editor">{(v.audio||[]).map(clip=><div key={clip.id}><DriveJournalAudio audio={clip} connected={driveConnected} language={language}/><button type="button" className="danger" onClick={()=>removeAudio(clip)}>{t('Remove')}</button></div>)}{audioFiles.map((file,index)=><div key={`${file.name}-${file.lastModified}-${index}`}><LocalJournalAudio file={file} language={language}/><button type="button" className="danger" onClick={()=>setAudioFiles(current=>current.filter((_,candidate)=>candidate!==index))}>{t('Remove')}</button></div>)}</div>}
    <div className="journal-media-pickers"><label className={`secondary journal-photo-picker${driveConnected?'':' disabled'}`}>{t('Add photos')}<input type="file" accept="image/*" multiple disabled={!driveConnected||busy} onChange={event=>{setPhotoFiles(current=>[...current,...Array.from(event.target.files||[])]);event.target.value=''}}/></label><label className={`secondary journal-photo-picker${driveConnected?'':' disabled'}`}>{t('Add audio')}<input type="file" accept={AUDIO_FILE_ACCEPT} multiple disabled={!driveConnected||busy} onChange={event=>{setAudioFiles(current=>[...current,...Array.from(event.target.files||[])]);event.target.value=''}}/></label></div>
    {!driveConnected&&<p className="journal-drive-note">{t('Connect Google Drive to add or view photos and audio. Notes remain available locally.')}</p>}
   </Fragment>:<Fragment key="itinerary-fields">
    {hasEndDetails?<><div className="two"><label>Time zone<input list="waypoint-time-zones" required value={v.timeZone} onChange={field('timeZone')}/></label><label>End time zone<input list="waypoint-time-zones" value={v.endTimeZone||''} onChange={field('endTimeZone')}/></label></div><div className="two"><label>Location<input value={v.location||''} onChange={field('location')}/></label><label>End location<input value={v.endLocation||''} onChange={field('endLocation')}/></label></div></>:<><label>Time zone<input list="waypoint-time-zones" required value={v.timeZone} onChange={field('timeZone')}/></label>{v.type!=='insurance'&&<label>Location<input value={v.location||''} onChange={field('location')}/></label>}</>}
    <div className="two"><label>Provider<input value={v.provider||''} onChange={field('provider')}/></label><label>Confirmation<input value={v.confirmation||''} onChange={field('confirmation')}/></label></div>
    <label>{t('Booked by')}<input value={v.bookedBy||''} onChange={field('bookedBy')} placeholder={t('Person who made the booking')}/></label>
    <label>Ticket / booking link<input type="url" pattern="https://.*" title="Use a secure https:// link" value={v.link||''} onChange={field('link')}/></label>
    <label>Source email link<input type="url" pattern="https://.*" title={canAccessSourceEmails?'Use a secure https:// link':'Source email can only be edited by the itinerary owner'} value={v.emailLink||''} disabled={!canAccessSourceEmails} onChange={field('emailLink')}/></label>
    <label>Status<select value={v.status} onChange={field('status')}><option value="confirmed">Confirmed</option><option value="pending">Pending</option><option value="planned">Planned</option></select></label>
    <label>Notes<textarea value={v.notes||''} onChange={field('notes')}/></label>
   </Fragment>}
   <div className="modal-actions">{!isNew&&<button type="button" className="danger" disabled={busy} onClick={onDelete}>Delete</button>}<span/><button type="button" className="secondary" disabled={busy} onClick={onClose}>Cancel</button><button disabled={busy}>{t(busy?'Saving…':'Save item')}</button></div>
  </>:<section className="item-json-panel" role="tabpanel"><p>{t(isNew?'Paste one item object, an array of items, or an object with an items array. Each item needs type, title, start, timeZone, and status; IDs are optional and will be replaced with fresh IDs.':'Overwrite this entry with one item object. The existing ID is preserved; JSON can update fields that are locked in the form.')}</p><label>{t('Item JSON')}<textarea className="item-json-editor" aria-label={t('Item JSON')} autoFocus value={json} onChange={event=>{setJson(event.target.value);setJsonError('')}} placeholder={localizedItemJsonExample(language)}/></label><p className={`item-json-status ${jsonError?'error':''}`} role="status">{jsonError||copyStatus}</p><div className="modal-actions">{!isNew&&<button type="button" className="danger" disabled={busy} onClick={onDelete}>Delete</button>}<span/><button type="button" className="secondary" disabled={busy} onClick={copyItem}>{t('Copy JSON')}</button><button type="button" className="secondary" disabled={busy} onClick={onClose}>Cancel</button><button disabled={busy}>{t(busy?'Saving…':isNew?'Add from JSON':'Overwrite from JSON')}</button></div></section>}
 </form></div>
}
